from pathlib import Path
import re

path = Path('src/server/managementPage.ts')
text = path.read_text(encoding='utf-8')
pattern = re.compile(r"function aiReflectionLineSvg\(items\)\{.*?\}\nfunction formatSeconds", re.S)
replacement = r'''function aiReflectionLineSvg(items){const rows=items||[],w=460,h=270,left=64,top=70,right=18,bottom=52,plotW=w-left-right,plotH=h-top-bottom;const valid=function(v){return v!==null&&v!==undefined&&v!==''&&Number.isFinite(Number(v))};const series=[{key:'reflection_understood',n:'reflection_understood_n',label:'相手の話を聞いて分かる',color:'#2774ee',shape:'circle',legendX:64,legendY:17},{key:'reflection_conveyed',n:'reflection_conveyed_n',label:'自分の考えを伝える',color:'#20a567',shape:'square',legendX:270,legendY:17},{key:'reflection_culture',n:'reflection_culture_n',label:'新しい言葉や文化に気づいた',color:'#f59e0b',shape:'diamond',legendX:64,legendY:40}];const has=rows.some(function(r){return series.some(function(s){return valid(r[s.key])})});let out='<svg viewBox=\"0 0 '+w+' '+h+'\" width=\"100%\" height=\"100%\" role=\"img\" aria-label=\"AI対話ふりかえり平均 4件法\">';if(!rows.length||!has)return out+'<text x=\"230\" y=\"135\" text-anchor=\"middle\" class=\"svg-label\">データなし</text></svg>';const x=function(i){return left+(rows.length<=1?plotW/2:i*plotW/(rows.length-1))},y=function(v){return top+plotH-(Number(v)-1)*plotH/3};const offsets=function(r){const result=[0,0,0],groups=new Map();series.forEach(function(s,si){if(!valid(r[s.key]))return;const key=Number(r[s.key]).toFixed(6),group=groups.get(key)||[];group.push(si);groups.set(key,group)});groups.forEach(function(group){if(group.length===2){result[group[0]]=-3;result[group[1]]=3}else if(group.length>=3){result[group[0]]=-4;result[group[1]]=0;result[group[2]]=4}});return result};const marker=function(shape,cx,cy,color,title){const t=title?'<title>'+esc(title)+'</title>':'';if(shape==='square')return '<g>'+t+'<rect x=\"'+(cx-5)+'\" y=\"'+(cy-5)+'\" width=\"10\" height=\"10\" rx=\"1\" fill=\"#fff\" stroke=\"'+color+'\" stroke-width=\"3\"/></g>';if(shape==='diamond')return '<g>'+t+'<polygon points=\"'+cx+','+(cy-6)+' '+(cx+6)+','+cy+' '+cx+','+(cy+6)+' '+(cx-6)+','+cy+'\" fill=\"#fff\" stroke=\"'+color+'\" stroke-width=\"3\"/></g>';return '<g>'+t+'<circle cx=\"'+cx+'\" cy=\"'+cy+'\" r=\"5\" fill=\"#fff\" stroke=\"'+color+'\" stroke-width=\"3\"/></g>'};[1,2,3,4].forEach(function(tick){const yy=y(tick);out+='<line x1=\"'+left+'\" y1=\"'+yy+'\" x2=\"'+(left+plotW)+'\" y2=\"'+yy+'\" stroke=\"#dfe7f2\" stroke-width=\"1\"/><text x=\"'+(left-20)+'\" y=\"'+(yy+6)+'\" text-anchor=\"middle\" class=\"reflection-axis-label\">'+tick+'</text>'});const every=Math.max(1,Math.ceil(rows.length/8));rows.forEach(function(r,i){if(i%every===0||i===rows.length-1)out+='<text x=\"'+x(i)+'\" y=\"'+(h-25)+'\" text-anchor=\"middle\" class=\"svg-label\">'+esc(String(r.date||'').slice(5))+'</text>'});series.forEach(function(item,si){let segment=[],segments=[];rows.forEach(function(r,i){if(valid(r[item.key])){const visualOffset=offsets(r)[si];segment.push(x(i)+','+(y(Number(r[item.key]))+visualOffset))}else if(segment.length){segments.push(segment);segment=[]}});if(segment.length)segments.push(segment);segments.forEach(function(points){if(points.length>1)out+='<polyline points=\"'+points.join(' ')+'\" fill=\"none\" stroke=\"'+item.color+'\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>'});rows.forEach(function(r,i){if(!valid(r[item.key]))return;const visualOffset=offsets(r)[si],value=formatChartValue(r[item.key]),count=Number(r[item.n]||0),title=String(r.date||'')+' '+item.label+': 平均 '+value+' (n='+count+')';out+=marker(item.shape,x(i),y(Number(r[item.key]))+visualOffset,item.color,title)});out+='<line x1=\"'+item.legendX+'\" y1=\"'+item.legendY+'\" x2=\"'+(item.legendX+22)+'\" y2=\"'+item.legendY+'\" stroke=\"'+item.color+'\" stroke-width=\"3\" stroke-linecap=\"round\"/>'+marker(item.shape,item.legendX+11,item.legendY,item.color,'')+'<text x=\"'+(item.legendX+28)+'\" y=\"'+(item.legendY+5)+'\" class=\"reflection-legend-label\">'+esc(item.label)+'</text>'});out+='<text x=\"'+left+'\" y=\"'+(h-4)+'\" class=\"svg-label\" style=\"font-size:11px;fill:#64748b\">1 = 次はがんばる　/　4 = よくできた</text>';return out+'</svg>'}
function formatSeconds'''
new_text, count = pattern.subn(lambda _m: replacement, text, count=1)
if count != 1:
    raise RuntimeError(f'expected one aiReflectionLineSvg function, found {count}')
path.write_text(new_text, encoding='utf-8')
print('AI reflection legend layout patched')
